import { PERMISSION_DEFINITIONS } from '../../constants/permissions.js';

/**
 * The OpenAPI document, GENERATED BY WALKING THE LIVE ROUTER.
 *
 * A hand-written spec is a second source of truth about the same API, and the
 * two diverge the first week nobody updates it. Worse, it diverges silently:
 * documentation that is merely out of date looks exactly like documentation
 * that is correct.
 *
 * So this reads Express's own route table. If a route exists, it is here; if
 * it was deleted, it vanishes. The spec cannot describe an endpoint that does
 * not exist, which is the one guarantee a hand-written file can never make.
 *
 * What it CANNOT derive is request and response body shapes — those live in
 * Zod schemas that would need a converter to express as JSON Schema. Rather
 * than half-describe them and imply more precision than exists, the spec
 * documents paths, methods, parameters, auth and the required permission, and
 * says plainly that bodies are validated server-side. An honest partial spec
 * beats a complete-looking one that lies.
 */

/**
 * The permissions a route's gate declares.
 *
 * `requirePermission` attaches them to the middleware it returns, because a
 * closure's captured values cannot be read back from its source and a second
 * hand-maintained list would drift from the routes it describes.
 */
function permissionOf(layer) {
  return layer.handle?.requiredPermissions ?? null;
}

/** Converts `/:id` to `/{id}` and collects the parameter names. */
function toOpenApiPath(expressPath) {
  const params = [];
  const path = expressPath.replace(/:([A-Za-z0-9_]+)/g, (_, name) => {
    params.push(name);
    return `{${name}}`;
  });
  return { path, params };
}

function normalise(layerPath) {
  return String(layerPath)
    .replace(/\\\//g, '/')
    .replace(/^\^/, '')
    .replace(/\$$/, '')
    .replace(/\(\?=\/\|\$\)/g, '')
    .replace(/\(\?:\(\[\^\\\/]\+\?\)\)/g, '')
    .replace(/\/\?$/, '');
}

/**
 * Walks a router stack, accumulating the mount prefix AND inherited permissions.
 *
 * The inherited part matters. A gate can sit on one route:
 *
 *   router.get('/', requirePermission('VIEW_X'), handler)
 *
 * or on a whole router:
 *
 *   router.use(requirePermission('VIEW_AUDIT_LOGS'))
 *
 * Both are real and both apply. The first version of this only looked inside
 * `route.stack`, so every audit-log endpoint was documented as merely
 * "authenticated" — UNDER-reporting the requirement, which is the direction
 * that sends someone building a client against a wrong assumption.
 *
 * Middleware applies in declaration order, so permissions accumulate as the
 * stack is walked and carry into anything mounted after them.
 */
function walk(stack, prefix, routes, inherited = []) {
  let carried = [...inherited];

  for (const layer of stack ?? []) {
    if (layer.route) {
      const own = layer.route.stack.map(permissionOf).find(Boolean) ?? [];
      const all = [...new Set([...carried, ...own])];

      for (const method of Object.keys(layer.route.methods).filter((m) => m !== '_all')) {
        routes.push({
          method: method.toUpperCase(),
          path: prefix + layer.route.path,
          requires: all.length > 0 ? all : null,
        });
      }
      continue;
    }

    if (layer.name === 'router' && layer.handle?.stack) {
      const mount = layer.regexp ? normalise(layer.regexp.source) : '';
      walk(layer.handle.stack, prefix + mount, routes, carried);
      continue;
    }

    // A bare `router.use(requirePermission(...))` applies to everything
    // declared after it on this router.
    const required = permissionOf(layer);
    if (required) carried = [...new Set([...carried, ...required])];
  }
}

/**
 * Every route the application actually serves.
 *
 * Takes the LIVE app — `req.app` inside a handler — rather than building a new
 * one. Calling `createApp()` per request spun up a fresh rate-limiter each
 * time (express-rate-limit says so loudly) and created a circular import
 * besides: app → routes → docs → app. Documenting the app that is actually
 * running is also simply more honest.
 */
export function collectRoutes(app) {
  if (!app?._router?.stack) {
    throw new TypeError('collectRoutes needs the running Express app');
  }

  const routes = [];
  walk(app._router?.stack, '', routes);

  return routes
    .filter((r) => r.path.startsWith('/api/'))
    .sort((a, b) => a.path.localeCompare(b.path) || a.method.localeCompare(b.method));
}

const TAG_OF = (path) => {
  const match = path.match(/^\/api\/v\d+\/([^/{]+)/);
  return match ? match[1] : 'root';
};

const CACHE = new WeakMap();

/**
 * Built once per app and cached.
 *
 * The route table is fixed after boot, so regenerating 168 operations on every
 * request would be work with no possible change in the answer.
 */
export function buildOpenApiDocument({ version = '0.1.0', app } = {}) {
  const cached = CACHE.get(app);
  if (cached) return cached;

  const routes = collectRoutes(app);
  const paths = {};
  const tags = new Set();

  for (const route of routes) {
    const { path, params } = toOpenApiPath(route.path);
    const tag = TAG_OF(path);
    tags.add(tag);

    paths[path] ??= {};
    paths[path][route.method.toLowerCase()] = {
      tags: [tag],
      summary: `${route.method} ${path}`,
      description: route.requires
        ? `Requires: ${route.requires.join(', ')}`
        : 'Requires authentication only.',
      security: path.includes('/auth/login') ? [] : [{ bearerAuth: [] }],
      parameters: params.map((name) => ({
        name,
        in: 'path',
        required: true,
        schema: { type: 'string', pattern: '^[0-9a-fA-F]{24}$' },
      })),
      responses: {
        200: { description: 'Success' },
        400: { description: 'Validation failed' },
        401: { description: 'Not authenticated' },
        403: { description: 'Permission denied' },
        404: { description: 'Not found' },
        422: { description: 'Refused by a domain rule' },
        429: { description: 'Rate limited' },
      },
      ...(route.requires ? { 'x-required-permissions': route.requires } : {}),
    };
  }

  const document = {
    openapi: '3.0.3',
    info: {
      title: 'Inventory Management API',
      version,
      description: [
        'Generated by walking the live Express router, so it cannot describe an',
        'endpoint that does not exist.',
        '',
        'Request and response bodies are validated by Zod schemas on the server',
        'and are deliberately NOT reproduced here: a second description of the',
        'same shapes would drift, and documentation that is out of date looks',
        'exactly like documentation that is correct.',
        '',
        'Every error response carries a stable machine `code`; match on that',
        'rather than on the message, which is free to change.',
      ].join('\n'),
    },
    servers: [{ url: '/', description: 'This server' }],
    components: {
      securitySchemes: {
        bearerAuth: {
          type: 'http',
          scheme: 'bearer',
          bearerFormat: 'JWT',
          description:
            'A 15-minute access token from POST /api/v1/auth/login. Refresh with the '
            + 'HttpOnly cookie against POST /api/v1/auth/refresh.',
        },
      },
      schemas: {
        Error: {
          type: 'object',
          properties: {
            success: { type: 'boolean', example: false },
            code: { type: 'string', example: 'INSUFFICIENT_STOCK' },
            message: { type: 'string' },
            errors: { type: 'array', items: { type: 'object' } },
            requestId: { type: 'string' },
          },
        },
      },
    },
    security: [{ bearerAuth: [] }],
    tags: [...tags].sort().map((name) => ({ name })),
    paths,
    // `label`, not `description`. The definitions have no `description` field
    // and never did, so every one of the 102 entries published `undefined`
    // from Phase 12 until this was spotted. The test asserted the ARRAY LENGTH
    // and nothing about its contents — which is how a spec can be complete,
    // correct in shape, and empty of meaning.
    'x-permissions': PERMISSION_DEFINITIONS.map((p) => ({
      code: p.code,
      module: p.module,
      label: p.label,
      restricted: p.restricted,
    })),
  };

  CACHE.set(app, document);
  return document;
}

export { PERMISSION_DEFINITIONS };
